class Solution {
public:
    int minChanges(vector<int>& nums, int k) {
        int n = nums.size(), P = n / 2, K = k + 1;
        vector<int> cntD(K, 0), ne(K + 1, 0);
        for (int i = 0; i < P; i++) {
            int a = nums[i], b = nums[n - 1 - i];
            int d = abs(a - b);
            cntD[d]++;
            int m = min(a, b), M = max(a, b);
            int lo = max(M, k - m) + 1;
            if (lo <= k) ne[lo]++;
        }
        for (int x = K - 2; x >= 0; x--) ne[x] += ne[x + 1];
        int best = INT_MAX;
        for (int x = 0; x < K; x++) {
            int elig = P - ne[x];
            best = min(best, 2 * (P - elig) + (elig - cntD[x]));
        }
        return best;
    }
};

